"""生成可审查的论文索引图 HTML 与 JSON 数据。"""
from __future__ import annotations

import json
import os

from .errors import ErrorCode, fail_from_exception, ok
from .query import get_graph_snapshot
from .semantic import list_relation_proposals


def export_graph_visualization(cfg, output_dir=None):
    """导出 self-contained HTML；更新时覆盖同一入口并保留 snapshot ID。"""
    output_dir = os.path.abspath(output_dir or os.path.join(cfg.kb_dir, "visualization"))
    try:
        snapshot_result = get_graph_snapshot(cfg)
        if not snapshot_result.ok:
            return snapshot_result
        semantic_result = list_relation_proposals(cfg)
        semantic_rows = semantic_result.data if semantic_result.ok else []
        payload = dict(snapshot_result.data)
        payload["semantic_relations"] = semantic_rows
        os.makedirs(output_dir, exist_ok=True)
        data_path = os.path.join(output_dir, "paper_index_graph.json")
        html_path = os.path.join(output_dir, "paper_index_graph.html")
        with open(data_path, "w", encoding="utf-8") as handle:
            json.dump(payload, handle, ensure_ascii=False, indent=2)
        embedded = json.dumps(payload, ensure_ascii=False).replace("</", "<\\/")
        document = r"""<!doctype html><html lang="zh-CN"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>Paper Index Graph</title>
<style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#080d17;color:#e8edf6;font:14px system-ui;overflow:hidden}
#bar{height:54px;display:flex;align-items:center;gap:12px;padding:8px 14px;background:#111a2a;border-bottom:1px solid #2a3850}button,select,label{background:#17243a;color:#e8edf6;border:1px solid #40506a;border-radius:6px;padding:6px 9px}label{border:0}.spacer{flex:1}.muted{color:#9cabc0;font-size:12px}
#stage{position:absolute;top:54px;left:0;right:320px;bottom:0}canvas{width:100%;height:100%;touch-action:none}#timelineControl{position:absolute;z-index:3;left:14px;top:70px;bottom:24px;width:34px;display:flex;flex-direction:column;align-items:center;gap:8px;padding:9px 5px;border:1px solid #40506a;border-radius:18px;background:#101827dd;box-shadow:0 8px 30px #0008}#timelineControl span{font-size:10px;color:#9cabc0;writing-mode:vertical-rl}#timelineScroll{flex:1;width:18px;writing-mode:vertical-lr;direction:rtl;accent-color:#35b9cf}#detail{position:absolute;top:54px;right:0;bottom:0;width:320px;background:#101827;border-left:1px solid #2a3850;padding:16px;overflow:auto}pre{white-space:pre-wrap;word-break:break-word;color:#cad4e4}.legend{display:grid;grid-template-columns:16px 1fr;gap:6px 8px;margin:12px 0}.sw{height:10px;margin-top:4px;border-radius:4px}.paper{background:#354766}.claim{background:#f3d58b}.pr{background:#35b9cf}.cite{background:#778398}.support{background:#55c77a}.contradict{background:#ef6a5b}.extend{background:#aa78e8}.use{background:#31b7a5}
@media(max-width:800px){#stage{right:0;bottom:220px}#detail{top:auto;width:100%;height:220px}}</style></head><body>
<div id="bar"><strong>Paper Index Graph</strong><span id="meta" class="muted"></span><span class="spacer"></span>
<label><input id="citations" type="checkbox"> 原始引用</label><label><input id="claims" type="checkbox" checked> 论点层</label>
<select id="mode"><option value="linked">两层联动</option><option value="papers">仅论文图</option><option value="claims">仅论点图</option></select>
<button id="demo">▶ 时间演示</button><button id="axis">沿时间轴</button><button id="fit">适应窗口</button><button id="reset">重置视角</button></div>
<div id="stage"><div id="timelineControl"><span>时间位置</span><input id="timelineScroll" type="range" min="-2000" max="2000" value="0" step="5" aria-label="上下移动时间轴"></div><canvas id="canvas"></canvas></div><aside id="detail"><h2>图例与详情</h2>
<div class="legend"><i class="sw paper"></i><span>论文实体（深色圆）</span><i class="sw claim"></i><span>论点（浅色菱形）</span><i class="sw pr"></i><span>论文脉络：画面由前驱指向继承者</span><i class="sw cite"></i><span>原始引用：引用者指向被引者，默认关闭</span><i class="sw support"></i><span>support</span><i class="sw contradict"></i><span>contradict</span><i class="sw extend"></i><span>extend</span><i class="sw use"></i><span>use</span></div>
<p class="muted">时间从上到下由早到晚；中心竖线为时间主轴。左侧滑条可在放大后上下移动。点击论点会同时高亮其所属论文。“时间演示”按年份依次展开论文和论点。候选关系会明确标注状态，不等同事实。</p><pre id="info">请选择对象</pre></aside>
<script>const DATA=__DATA__,canvas=document.getElementById('canvas'),ctx=canvas.getContext('2d'),stage=document.getElementById('stage'),info=document.getElementById('info');
const state={yaw:.55,pitch:-.18,zoom:1,panX:0,panY:0,selected:null,hover:null,showCitations:false,showClaims:true,mode:'linked',revealIndex:null};let projected=[],drawnEdges=[],demoTimer=null;
const years=[...new Set(DATA.papers.map(p=>p.preprint_year||p.year).filter(Boolean))].sort((a,b)=>a-b),yearIndex=new Map(years.map((y,i)=>[y,i]));
function hash(s){let h=2166136261;for(const c of String(s)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}function angle(id){return(hash(id)%6283)/1000}
const nodes=[],byId=new Map();for(const p of DATA.papers){const y=p.preprint_year||p.year,band=y?yearIndex.get(y):-1,a=angle(p.paper_id),r=75+Math.max(0,band)*13,n={id:p.paper_id,type:'paper',raw:p,x:Math.cos(a)*r,y:-(band+1)*145,z:Math.sin(a)*r,year:y||'年份未知',band};nodes.push(n);byId.set(n.id,n)}
const claimCount={};for(const c of DATA.claims||[]){const parent=byId.get(c.paper_id);if(!parent)continue;const i=claimCount[c.paper_id]=(claimCount[c.paper_id]||0)+1,a=angle(c.claim_id)+i*.7,n={id:c.claim_id,type:'claim',raw:c,x:parent.x+Math.cos(a)*(34+i*3),y:parent.y+(i%3-1)*16,z:parent.z+Math.sin(a)*(34+i*3),year:parent.year,band:parent.band};nodes.push(n);byId.set(n.id,n)}
const edges=[];function edge(id,a,b,type,raw,direction){if(byId.has(a)&&byId.has(b))edges.push({id,a,b,type,raw,direction})}
for(const e of DATA.paper_relations||[])edge(e.rel_id,e.dst_paper,e.src_paper,'paper_relation',e,'前驱 → 继承者（画面方向；存储为 src=继承者,dst=前驱）');
for(const e of DATA.citations||[])if(e.internal)edge(`cite:${e.from_paper}:${e.to_raw}`,e.from_paper,e.to_paper,'citation',e,'引用者 → 被引者');
for(const e of DATA.claim_relations||[])edge(e.rel_id,e.src_claim,e.dst_claim,e.kind||'claim_relation',e,'src_claim → dst_claim');
for(const c of DATA.claims||[])edge(`owns:${c.paper_id}:${c.claim_id}`,c.paper_id,c.claim_id,'ownership',{paper_id:c.paper_id,claim_id:c.claim_id},'论文所属（无语义箭头）');
for(const e of DATA.semantic_relations||[])edge(e.proposal_id,e.dst_paper,e.src_paper,'semantic_candidate',e,'前驱 → 继承者候选；非原始事实');
function revealed(n){return state.revealIndex===null||n.band<0||n.band<=state.revealIndex}function visible(e){if(!revealed(byId.get(e.a))||!revealed(byId.get(e.b)))return false;if(e.type==='citation')return state.showCitations&&state.mode!=='claims';if(e.type==='ownership')return state.showClaims&&state.mode!=='papers';if(['support','contradict','extend','use','claim_relation'].includes(e.type))return state.showClaims&&state.mode!=='papers';return state.mode!=='claims'}
function project(n,zoom=state.zoom,panX=state.panX,panY=state.panY){let x=n.x,z=n.z,y=n.y;const cy=Math.cos(state.yaw),sy=Math.sin(state.yaw),cp=Math.cos(state.pitch),sp=Math.sin(state.pitch),x1=x*cy-z*sy,z1=x*sy+z*cy,y1=y*cp-z1*sp,z2=y*sp+z1*cp,scale=zoom;return{x:canvas._w/2+panX+x1*scale,y:canvas._h/2+panY-y1*scale,z:z2,scale}}
function visibleNodes(){return nodes.filter(n=>revealed(n)&&!(state.mode==='papers'&&n.type==='claim'))}
function fitPoints(){const pts=[...visibleNodes()];for(let i=0;i<years.length;i++){const y=-(i+1)*145;for(const x of [-180,180])for(const z of [-180,180])pts.push({x,y,z})}return pts}
function fitView(){if(!canvas._w||!canvas._h)return;const pts=fitPoints().map(n=>project(n,1,0,0));if(!pts.length){Object.assign(state,{zoom:1,panX:0,panY:0});draw();return}const minX=Math.min(...pts.map(p=>p.x)),maxX=Math.max(...pts.map(p=>p.x)),minY=Math.min(...pts.map(p=>p.y)),maxY=Math.max(...pts.map(p=>p.y)),pad=Math.max(34,Math.min(canvas._w,canvas._h)*.07),bw=Math.max(1,maxX-minX),bh=Math.max(1,maxY-minY),zoom=Math.max(.04,Math.min(2.2,Math.min((canvas._w-2*pad)/bw,(canvas._h-2*pad)/bh))),cx=(minX+maxX)/2,cy=(minY+maxY)/2;state.zoom=zoom;state.panX=-(cx-canvas._w/2)*zoom;state.panY=-(cy-canvas._h/2)*zoom;draw()}
let resizeFrame=0;function resize(){const d=devicePixelRatio||1;canvas.width=Math.max(1,Math.round(stage.clientWidth*d));canvas.height=Math.max(1,Math.round(stage.clientHeight*d));canvas.style.width=`${stage.clientWidth}px`;canvas.style.height=`${stage.clientHeight}px`;ctx.setTransform(d,0,0,d,0,0);canvas._w=stage.clientWidth;canvas._h=stage.clientHeight;cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(fitView)}
function levels(){if(!state.selected)return new Map();let starts=[];if(state.selected.kind==='node')starts=[state.selected.value.id];else starts=[state.selected.value.a,state.selected.value.b];const dist=new Map(starts.map(x=>[x,0])),q=[...starts];while(q.length){const cur=q.shift(),d=dist.get(cur);if(d>=2)continue;for(const e of edges.filter(visible)){if(e.a!==cur&&e.b!==cur)continue;const next=e.a===cur?e.b:e.a;if(!dist.has(next)){dist.set(next,d+1);q.push(next)}}}return dist}
function style(e,dist){const colors={paper_relation:'#35b9cf',citation:'#778398',ownership:'#c7b98a',support:'#55c77a',contradict:'#ef6a5b',extend:'#aa78e8',use:'#31b7a5',claim_relation:'#8fa5bb',semantic_candidate:'#f2b84b'},c=colors[e.type]||'#8fa5bb';let width=e.type==='paper_relation'?2.8:e.type==='citation'?1:1.5,alpha=e.type==='citation'?.35:e.type==='ownership'?.45:.72,gap=0;if(state.selected){const da=dist.get(e.a),db=dist.get(e.b),d=Math.min(da??99,db??99);if(state.selected.kind==='edge'&&state.selected.value===e){width=5;gap=1;alpha=1}else if(d===0){width=3.4;gap=11;alpha=1}else if(d===1){width=1.9;gap=25;alpha=.85}else alpha=.12}return{c,width,alpha,gap}}
function line(a,b,s,arrow=true){ctx.save();ctx.strokeStyle=s.c;ctx.globalAlpha=s.alpha;ctx.lineWidth=s.width;ctx.setLineDash(s.gap?[9,s.gap]:[]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.setLineDash([]);if(arrow){const q=.82,x=a.x+(b.x-a.x)*q,y=a.y+(b.y-a.y)*q,ang=Math.atan2(b.y-a.y,b.x-a.x);ctx.fillStyle=s.c;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-8*Math.cos(ang-.45),y-8*Math.sin(ang-.45));ctx.lineTo(x-8*Math.cos(ang+.45),y-8*Math.sin(ang+.45));ctx.fill()}ctx.restore()}
function plane(year,index){const y=-(index+1)*145,pts=[[-170,y,-170],[170,y,-170],[170,y,170],[-170,y,170]].map(([x,y,z])=>project({x,y,z}));ctx.save();ctx.strokeStyle='#657a99';ctx.globalAlpha=.18;ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.stroke();ctx.fillStyle='#91a7c7';ctx.globalAlpha=.7;ctx.fillText(String(year),pts[0].x,pts[0].y);ctx.restore()}
function timeAxis(){if(!years.length)return;const a=project({x:0,y:-145,z:0}),b=project({x:0,y:-years.length*145,z:0});line(a,b,{c:'#d8e5f8',width:3,alpha:.72,gap:0},false)}
function draw(){ctx.clearRect(0,0,canvas._w,canvas._h);years.forEach((y,i)=>{if(state.revealIndex===null||i<=state.revealIndex)plane(y,i)});timeAxis();if(nodes.some(n=>n.type==='paper'&&n.year==='年份未知'))plane('年份未知',-1);const dist=levels();projected=nodes.filter(revealed).map(n=>({n,p:project(n)})).sort((a,b)=>a.p.z-b.p.z);drawnEdges=[];for(const e of edges.filter(visible)){const a=project(byId.get(e.a)),b=project(byId.get(e.b));line(a,b,style(e,dist),e.type!=='ownership');drawnEdges.push({e,a,b})}for(const o of projected){const n=o.n;if(state.mode==='papers'&&n.type==='claim')continue;const p=o.p,d=dist.get(n.id),selected=state.selected&&state.selected.kind==='node'&&state.selected.value===n,hovered=state.hover&&state.hover.kind==='node'&&state.hover.value===n,r=(n.type==='paper'?7:6)*(d===0?1.5:d===1?1.25:1)*Math.max(.7,p.scale);ctx.save();ctx.globalAlpha=state.selected&&d===undefined?.22:(state.mode==='claims'&&n.type==='paper'?.58:1);if(n.type==='paper'){ctx.fillStyle=d===0?'#2676b9':'#354766';ctx.strokeStyle=d===0||hovered?'#ffffff':'#9ec7ff';ctx.lineWidth=d===0||hovered?3:2;ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2)}else{ctx.fillStyle='#f3d58b';ctx.strokeStyle=hovered?'#ffffff':'#fff3cc';ctx.beginPath();ctx.moveTo(p.x,p.y-r);ctx.lineTo(p.x+r,p.y);ctx.lineTo(p.x,p.y+r);ctx.lineTo(p.x-r,p.y);ctx.closePath()}ctx.fill();ctx.stroke();if(n.type==='paper'&&(selected||d===0||hovered||(!state.selected&&state.zoom>=.24))){ctx.fillStyle='#e8edf6';ctx.font='12px system-ui';ctx.fillText((n.raw.title||n.id).slice(0,34),p.x+r+5,p.y+4)}ctx.restore()}}
function distance(px,py,a,b){const dx=b.x-a.x,dy=b.y-a.y,l=dx*dx+dy*dy||1,t=Math.max(0,Math.min(1,((px-a.x)*dx+(py-a.y)*dy)/l));return Math.hypot(px-(a.x+t*dx),py-(a.y+t*dy))}
function pick(x,y){let best=null,bd=16;for(const o of projected){const d=Math.hypot(x-o.p.x,y-o.p.y);if(d<bd){best={kind:'node',value:o.n};bd=d}}if(best)return best;bd=7;for(const o of drawnEdges){const d=distance(x,y,o.a,o.b);if(d<bd){best={kind:'edge',value:o.e};bd=d}}return best}
function show(sel){state.selected=sel;if(!sel){info.textContent='请选择对象';draw();return}const value=sel.value,raw=value.raw||value;info.textContent=JSON.stringify({object_type:sel.kind==='node'?value.type:value.type,id:value.id,direction:value.direction,data:raw,evidence:raw.evidence||raw.evidence_refs||null,generated_by:raw.generated_by||null,verification_status:raw.verification_status||null},null,2);draw()}
let drag=null;canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,shift:e.shiftKey};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag){const next=pick(e.offsetX,e.offsetY);if((next&&next.value)!==(state.hover&&state.hover.value)){state.hover=next;canvas.style.cursor=next?'pointer':'grab';draw()}return}const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;if(drag.shift){state.panX+=dx;state.panY+=dy}else{state.yaw+=dx*.008;state.pitch=Math.max(-1.2,Math.min(1.2,state.pitch+dy*.006))}draw()};canvas.onpointerleave=()=>{if(!drag&&state.hover){state.hover=null;canvas.style.cursor='grab';draw()}};canvas.onpointerup=e=>{if(drag&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)<4)show(pick(e.offsetX,e.offsetY));drag=null};canvas.onwheel=e=>{e.preventDefault();state.zoom=Math.max(.04,Math.min(3,state.zoom*Math.exp(-e.deltaY*.001)));draw()};
const timelineScroll=document.getElementById('timelineScroll'),demo=document.getElementById('demo');function syncScroll(){timelineScroll.value=String(Math.max(-2000,Math.min(2000,state.panY)))}timelineScroll.oninput=e=>{state.panY=Number(e.target.value);draw()};function stopDemo(){clearInterval(demoTimer);demoTimer=null;state.revealIndex=null;demo.textContent='▶ 时间演示';draw()}demo.onclick=()=>{if(demoTimer){stopDemo();return}state.revealIndex=-1;demo.textContent='■ 停止演示';draw();demoTimer=setInterval(()=>{state.revealIndex++;if(state.revealIndex>=years.length){stopDemo();return}draw()},850)};
document.getElementById('citations').onchange=e=>{state.showCitations=e.target.checked;draw()};document.getElementById('claims').onchange=e=>{state.showClaims=e.target.checked;fitView()};document.getElementById('mode').onchange=e=>{state.mode=e.target.value;fitView()};document.getElementById('fit').onclick=()=>{fitView();syncScroll()};document.getElementById('reset').onclick=()=>{stopDemo();Object.assign(state,{yaw:.55,pitch:-.18,selected:null});info.textContent='请选择对象';fitView();syncScroll()};document.getElementById('axis').onclick=()=>{Object.assign(state,{yaw:0,pitch:0});fitView();syncScroll()};
document.getElementById('meta').textContent=`${DATA.snapshot_id} · ${DATA.papers.length} papers · ${(DATA.claims||[]).length} claims`;new ResizeObserver(resize).observe(stage);resize();</script></body></html>""".replace("__DATA__", embedded)
        with open(html_path, "w", encoding="utf-8") as handle:
            handle.write(document)
    except Exception as exc:
        return fail_from_exception(exc, location="visualization.export_graph_visualization",
                                   code=ErrorCode.WRITE_ERROR, message=str(exc))
    return ok({"html": html_path, "json": data_path,
               "snapshot_id": payload["snapshot_id"]})
